mapper.select:
SELECT , WET.* FROM WORK_EFFORT_TYPE_CONTENT WETC INNER JOIN WORK_EFFORT_TYPE WET ON WET.WORK_EFFORT_TYPE_ID = WETC.WORK_EFFORT_TYPE_ID INNER JOIN CONTENT C ON C.CONTENT_ID = WETC.CONTENT_ID WHERE ( WETC.WE_TYPE_CONTENT_TYPE_ID = 'REPORT' OR WETC.WE_TYPE_CONTENT_TYPE_ID = 'JREPORT') AND WETC.IS_VISIBLE = 'Y'
AND WETC.WORK_EFFORT_TYPE_ID = #{workEffortTypeId}
AND WETC.WORK_EFFORT_TYPE_ID IS NOT NULL
AND WETC.CONTENT_ID = #{reportContentId} AND WET.PARENT_TYPE_ID = #{parentTypeId}
